(function(root){
  function quantile(values,p){if(!values.length)return null;const a=[...values].sort((x,y)=>x-y);return a[Math.max(0,Math.ceil(p*a.length)-1)];}
  function summarize(rows){const e=rows.filter(r=>r[5]!==null),late=e.filter(r=>r[6]===1),groups=[0,1].map(flag=>{const a=e.filter(r=>r[6]===flag&&r[7]!==null);return {n:a.length,low:a.filter(r=>r[7]<=2).length,score:a.reduce((s,r)=>s+r[7],0),avg:a.length?a.reduce((s,r)=>s+r[7],0)/a.length:null};});return {orders:rows.length,eligible:e.length,late:late.length,onTime:e.length?1-late.length/e.length:null,p90:quantile(e.map(r=>r[5]),.9),median:quantile(e.map(r=>r[5]),.5),reviews:groups,item:rows.reduce((s,r)=>s+r[8],0)/100,freight:rows.reduce((s,r)=>s+r[9],0)/100,missing:rows.filter(r=>r[7]===null).length};}
  function filter(rows,dims,f){return rows.filter(r=>(!f.year||dims.months[r[0]].startsWith(f.year))&&(f.state===''||r[1]===Number(f.state))&&(f.category===''||r[2]===Number(f.category)));}
  function sellers(rows,dims,minimum=100){const groups=new Map();for(const r of rows){const name=dims.sellers[r[3]];if(r[5]===null||!name.startsWith('Seller '))continue;let v=groups.get(name);if(!v){v={name,n:0,late:0,days:0,reviewed:0,score:0};groups.set(name,v);}v.n++;v.late+=r[6];v.days+=r[5];if(r[7]!==null){v.reviewed++;v.score+=r[7];}}return [...groups.values()].filter(v=>v.n>=minimum).map(v=>({...v,rate:v.late/v.n,mean:v.days/v.n,avg:v.reviewed?v.score/v.reviewed:null}));}
  const api={quantile,summarize,filter,sellers};if(typeof module!=='undefined')module.exports=api;else root.Analysis=api;
})(typeof window!=='undefined'?window:globalThis);
